(6219413, 918743, 123411, '<td valign="top">Nice Bokeh work.</td>', 'Nice Bokeh work.', '2010-11-10 20:29:33.000000', NULL, 1),
(6219418, 918947, 108069, '<td valign="top">I''m in this challenge so I''m not voting but I give this a 9 and mine a 5 so overall you''ve got a +2 after the head to head fight. Pretty damn cool.</td>', 'I''m in this challenge so I''m not voting but I give this a 9 and mine a 5 so overall you''ve got a +2 after the head to head fight. Pretty damn cool.', '2010-11-10 20:34:03.000000', NULL, 1),
(6219420, 918666, 108069, '<td valign="top">Fing awesome. My kind of shot. Nice work.</td>', 'Fing awesome. My kind of shot. Nice work.', '2010-11-10 20:36:25.000000', NULL, 1),
(6219477, 917986, 83313, '<td valign="top">There is a lack of clarity to this photo and I think most of it is due to the use of excessive JPEG compression. Your file size of only 36k indicates a highly compressed image and that is what is robbing a lot of the detail and sharpness from this image. I can see obvious compression artifacts around the lighthouse. Check your compression settings when you save your file. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit.</td>', 'There is a lack of clarity to this photo and I think most of it is due to the use of excessive JPEG compression. Your file size of only 36k indicates a highly compressed image and that is what is robbing a lot of the detail and sharpness from this image. I can see obvious compression artifacts around the lighthouse. Check your compression settings when you save your file. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit.', '2010-11-10 21:43:49.000000', NULL, 1),
(6219484, 918924, 83313, '<td valign="top">Sharp and well detailed, but it comes off a bit flat looking to me. I think it could benefit from a little more visual pop. Some contrast and saturation, perhaps, or even a touch of tonemapping, if you have any of that sort of software.</td>', 'Sharp and well detailed, but it comes off a bit flat looking to me. I think it could benefit from a little more visual pop. Some contrast and saturation, perhaps, or even a touch of tonemapping, if you have any of that sort of software.', '2010-11-10 21:50:12.000000', NULL, 1),
(6219487, 919169, 51747, '<td valign="top">It''s a really cool image. Not finding relevance to the challenge topic.</td>', 'It''s a really cool image. Not finding relevance to the challenge topic.', '2010-11-10 21:52:59.000000', NULL, 1),
(6219506, 919030, 113411, '<td valign="top">I like the clarity and the composition of the shot. I wish it were a tad brighter! I gave it a 9.</td>', 'I like the clarity and the composition of the shot. I wish it were a tad brighter! I gave it a 9.', '2010-11-10 22:06:35.000000', NULL, 1),
