(6220144, 919016, 29777, '<td valign="top">This would be more interesting with softer lighting that brings out the textures. The image overall seems soft. What is the subject here?</td>', 'This would be more interesting with softer lighting that brings out the textures. The image overall seems soft. What is the subject here?', '2010-11-11 15:10:47.000000', NULL, 1),
(6220146, 919116, 29777, '<td valign="top">This is a tough shot. The background is bright and busy, this takes attention away from the dog. A shallow depth of field is good for this type of shot, but focus on the eyes is important.</td>', 'This is a tough shot. The background is bright and busy, this takes attention away from the dog. A shallow depth of field is good for this type of shot, but focus on the eyes is important.', '2010-11-11 15:14:28.000000', NULL, 1),
