(6221555, 918842, 108580, '<td valign="top">Lovely! City nestled in the glow. Great exposure and composition.</td>', 'Lovely! City nestled in the glow. Great exposure and composition.', '2010-11-13 11:29:30.000000', NULL, 1),
(6221560, 918655, 108580, '<td valign="top">Very imaginative. I like the grain/noise. Others here won''t.</td>', 'Very imaginative. I like the grain/noise. Others here won''t.', '2010-11-13 11:31:53.000000', NULL, 1),
(6221561, 919120, 108580, '<td valign="top">Great concept and title. Well shot.</td>', 'Great concept and title. Well shot.', '2010-11-13 11:32:20.000000', NULL, 1),
(6221564, 918876, 108580, '<td valign="top">Very appealing automotive image. HDR processing would give this such impact, but I know it''s basic editing.</td>', 'Very appealing automotive image. HDR processing would give this such impact, but I know it''s basic editing.', '2010-11-13 11:34:34.000000', NULL, 1),
(6221575, 918262, 108580, '<td valign="top">Superb minimalist image. I fear the unsharp horison will knock off a few points. So similar to another shot here except for the orientation of the moons shadow. Really nicely balanced and processed.</td>', 'Superb minimalist image. I fear the unsharp horison will knock off a few points. So similar to another shot here except for the orientation of the moons shadow. Really nicely balanced and processed.', '2010-11-13 11:41:39.000000', NULL, 1),
