(6225371, 919013, 108580, '<td valign="top"><img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=86447" rel="nofollow" target="_blank">LydiaToo</a>, I did, I gave it a 9...</td>', ' LydiaToo, I did, I gave it a 9...', '2010-11-17 01:54:12.000000', NULL, 0),
